  {
    let calls = 0; const reason = { x: 1 };
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw reason; return 'ok'; } });
    const [r1, r2] = await Promise.allSettled([c.get('k'), c.get('k')]);
