  // 2. Rejection not cached; all waiters share reason; retry works.
  {
    let calls = 0; const reason = { x: 1 };
    const c = createCache({ now: () => 0, load: () => { calls++; if (calls === 1) throw reason; return 'ok'; } });
    const [r1, r2] = await Promise.allSettled([c.get('k'), c.get('k')]);
    assert.equal(r1.reason, reason); assert.equal(r2.reason, reason);
    assert.equal(await c.get('k'), 'ok'); assert.equal(calls, 2);
  }
  // 3. Detached flight rejecting must not unregister newer flight.
  {
    const gates = [d(), d()]; let calls = 0;
    const c = createCache({ now: () => 0, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.invalidate('k'); const b = c.get('k'); await tick();
    gates[0].reject('boom'); await assert.rejects(a, e => e === 'boom');
    c.get('k'); assert.equal(calls, 2);
    gates[1].resolve('v'); assert.equal(await b, 'v');
  }
  // 4. set wins over pending load; TTL not restarted; expiry starts fresh load.
  {
    let t = 0; const gates = [d(), d()]; let calls = 0;
    const c = createCache({ now: () => t, ttlMs: 10, load: () => gates[calls++].promise });
    const a = c.get('k'); await tick();
    c.set('k', 'manual');
    gates[0].resolve('loaded'); assert.equal(await a, 'loaded');
    assert.equal(await c.get('k'), 'manual');
    t = 10; const b = c.get('k'); await tick(); assert.equal(calls, 2);
    gates[1].resolve('later'); assert.equal(await b, 'later');
    assert.equal(c.size, 1);
  }
  // 5. load calling invalidate synchronously: its value not stored.
  {
    let calls = 0; let c;
    c = createCache({ now: () => 0, load: k => { calls++; if (calls === 1) c.invalidate(k); return 'v' + calls; } });
    assert.equal(await c.get('k'), 'v1');
    assert.equal(c.size, 0);
    assert.equal(await c.get('k'), 'v2'); assert.equal(calls, 2);
  }
  // 6. load reading own key joins its flight; clear detaches all.
  {
    let calls = 0; let c; let inner;
    c = createCache({ now: () => 0, load: k => { calls++; inner = c.get(k); return 'v'; } });
    const p = c.get('k'); await tick();
    assert.equal(calls, 1);
    assert.equal(await p, 'v'); assert.equal(await inner, 'v');
  }
  // 7. ttlMs=0 dedups unsettled but never reuses settled.
  {
    let calls = 0; const c = createCache({ now: () => 0, ttlMs: 0, load: () => ++calls });
    assert.deepEqual(await Promise.all([c.get('k'), c.get('k')]), [1, 1]);
    assert.equal(await c.get('k'), 2); assert.equal(c.size, 0);
  }
  console.log('all ok');
})().catch(e => { console.error(e); process.exit(1); });
